// Prépare la requête d'analyse pour Claude (vision + texte).
// On télécharge la photo nous-mêmes et on l'envoie en base64 : plus fiable
// qu'un simple lien (évite les blocages robots.txt et les redirections).
// this.helpers.httpRequest est l'outil de requête HTTP intégré à n8n,
// disponible dans les nœuds Code (pas de fetch() natif dans ce sandbox).
const p = $json.body || {};
if (!p.nom || !p.image_url) {
  throw new Error("Champs obligatoires : nom, image_url (+ prix_fcfa, argument conseillés)");
}

const reponseImage = await this.helpers.httpRequest({
  url: p.image_url,
  encoding: 'arraybuffer',
  returnFullResponse: true,
});
const typeImage = reponseImage.headers['content-type'] || 'image/jpeg';
const imageBase64 = Buffer.from(reponseImage.body).toString('base64');

const contenu = [
  { type: 'image', source: { type: 'base64', media_type: typeImage, data: imageBase64 } },
  {
    type: 'text',
    text: `Analyse ce produit vendu en Côte d'Ivoire.\nNom : ${p.nom}\nPrix : ${p.prix_fcfa ?? 'non précisé'} FCFA\nArgument principal : ${p.argument ?? 'non précisé'}\nLangues : ${p.langues ?? 'français'}`
  }
];
const corps = {
  model: $env.CLAUDE_MODEL || 'claude-haiku-4-5-20251001',
  max_tokens: 1024,
  system: `Tu es un analyste marketing pour le marché ivoirien et ouest-africain. À partir de la photo et des infos, réponds UNIQUEMENT en JSON : {\"categorie\":\"...\",\"description_visuelle\":\"ce qu'on voit sur la photo\",\"arguments_vente\":[\"3 à 5 arguments\"],\"audience_probable\":{\"genre\":\"tous|femmes|hommes\",\"age_min\":18,\"age_max\":55,\"centres_interet\":[\"...\"]},\"angle_publicitaire\":\"l'angle le plus vendeur\"}`,
  messages: [{ role: 'user', content: contenu }]
};
return [{ json: { corps, produit: p } }];

// Extrait la fiche produit JSON de la réponse de Claude.
// On prend uniquement ce qui est entre la première { et la dernière } :
// évite les erreurs si Claude ajoute du texte avant/après le JSON.
const texte = ($json.content || []).find(b => b.type === 'text')?.text ?? '{}';
const debut = texte.indexOf('{');
const fin = texte.lastIndexOf('}');
const propre = (debut !== -1 && fin !== -1) ? texte.slice(debut, fin + 1) : texte.trim();
const fiche = JSON.parse(propre);
const produit = $('Préparer l\'analyse').first().json.produit;
return [{ json: { produit, fiche } }];
